import pytest
from isort.comments import add_to_line

def test_add_to_line_with_comments():
    assert add_to_line(['Comment1', 'Comment2'], 'Original string') == 'Original stringComment1; Comment2'

def test_add_to_line_with_no_comments():
    assert add_to_line([], 'Original string') == 'Original string'

def test_add_to_line_with_removed():
    assert add_to_line(None, 'Original string', removed=True) == 'Original string'

def test_add_to_line_with_empty_string():
    assert add_to_line(['Comment1'], '') == 'Comment1'

def test_add_to_line_unique_comments():
    assert add_to_line(['Comment1', 'Comment2', 'Comment1'], 'Original string') == 'Original stringComment1; Comment2'

def test_add_to_line_with_none_comments():
    assert add_to_line(None, 'Original string') == 'Original string'

def test_add_to_line_with_remove_and_comments():
    assert add_to_line(['Comment1'], 'Original string', removed=True) == 'Original string'
